export function normalizeThermalOverrides(overrides={}){
 if(!overrides||typeof overrides!=='object'||Array.isArray(overrides))return overrides;
 const normalized={...overrides};
 for(const group of ['items','plans']){
  const records=overrides[group];
  if(!records){delete normalized[group];continue;}
  if(typeof records!=='object'||Array.isArray(records))continue;
  const entries=Object.entries(records).filter(([,patch])=>!(patch&&typeof patch==='object'&&!Array.isArray(patch)&&Object.keys(patch).length===0));
  if(entries.length)normalized[group]=Object.fromEntries(entries.map(([id,patch])=>[id,patch&&typeof patch==='object'&&!Array.isArray(patch)?{...patch}:patch]));
  else delete normalized[group];
 }
 return normalized;
}
